# Rebuild edits: doubt ablation + closure amplification with given alpha
def build(alpha):
    import torch, numpy as np
    d_np = np.load('/work/d_closure.npy').astype(np.float32)
    d_np = d_np / np.linalg.norm(d_np)
    d_t = torch.from_numpy(d_np).float()
    doubt_full = {12:[55], 13:[138], 14:[1443], 15:[331,20], 16:[998,49], 17:[182], 18:[1261,133], 19:[663,70,353], 20:[1111,106], 21:[44], 22:[194,684,11,122], 23:[36,168,118,57,40]}
    for L in range(24):
        name = f'model.language_model.layers.{L}.mlp.down_proj.weight'
        W = load_original(name).clone()
        if L in doubt_full:
            for u in doubt_full[L]:
                W[:, u] = 0.0
        if alpha > 0 and L >= 14:
            W = W + alpha * torch.outer(d_t, d_t @ W)
        save_edit(name, W)
build(0.5)
print('built alpha=0.5')

